import java.util.Scanner;

public class AK375 {
    public static Scanner cin = new Scanner(System.in);

    public String ak375(int n, String str) {
        int res1 = 0;
        int res2 = 0;
        int currentOutsideLen = 0;
        boolean insideParen = false;

        for (int i = 0; i < n; i++) {
            char c = str.charAt(i);
            if (c == '(') {
                insideParen = true;
                res2++;
            } else if (c == ')') {
                insideParen = false;
                if (currentOutsideLen > res1) {
                    res1 = currentOutsideLen;
                }
                currentOutsideLen = 0;
            } else {
                if (insideParen) {
                    // inside parentheses, do nothing for res1
                } else {
                    currentOutsideLen++;
                }
            }
        }
        if (currentOutsideLen > res1) {
            res1 = currentOutsideLen;
        }

        return res1 + " " + res2;
    }

    public static void main(String[] args) {
        while (cin.hasNext()) {
            int n = cin.nextInt();
            String str = cin.next();
            String res = new AK375().ak375(n, str);
            System.out.println(res);
        }
    }
}
